def bm_match(text, pat):
    n, m = len(text), len(pat)
    comparisons = 0

    if m == 0:
        return 0, comparisons
    if m > n:
        return -1, comparisons

    # 各文字のパターン内での最後の出現位置
    last = {c: i for i, c in enumerate(pat)}

    start = 0
